def find(nums, target):
    lo, hi = 0, len(nums) - 1
    while lo <= hi:
        mid = (lo + hi) // 2
        if nums[mid] == target:
            return mid
        if nums[mid] < target:
            lo = mid + 1
        else:
            hi = mid - 1
    return -1

print(find([2, 5, 8, 12, 16, 23, 38, 56, 72, 91], 23))
print(find([2, 5, 8], 4))
